  patch={'id':s['id'],'case':case,'contract':canonpath,'batch':s['batch'],'source':s['source'],'source_raw_sha256_input_guard':source_guard,'exact_original_current_row':current,'current_full_row_guard_sha256':rowguard(current),'proposed_full_row':proposed,'evidence':{'reviewer':'math81_boundary_hall_step3_attempt2','disposition':'corrected' if corrected else 'upheld-specific-template-review','reason':reason,'actual_current_claim_facts_entire_argument_read':True}}
